	/* 
	 ** 公用弹窗组件。由于不知道弹窗会展示什么内容，所以内容部分需要在具体的页面中以slot的形式传入 
	 */
	
export default {
	props: {
		// 是否显示弹窗
		isShowDialog: {
			type: Boolean,
			required: true,
			default() {
				return false;
			}
		},
		// 点击mask是否关闭弹窗
		isMaskClose: {
			type: Boolean,
			required: false,
			default() {
				return false;
			}
		},
		
		// 是否显示取消按钮
		isShowCancelBtn: {
			type: Boolean,
			required: false,
			default() {
				return false;
			}
		}
	},
	data() {
		return {
			isShowDialogData: false
		};
	},

	created() {
		// 值类型的props不允许直接修改，这里赋值给data解决
		// this.isShowDialogData = this.isShowDialog;
	},

	methods: {
		// 点击mask
		tapMask(){
			if(this.isMaskClose){
				this.cancelEvt();
			}
		},
		// 关闭弹窗
		cancelEvt() {
			this.isShowDialogData = false;
			this.$emit('closeDialog');
		},

		// 点击确定按钮
		confirmEvt() {
			this.$emit('confirmDialog');
		}
	},

	watch: {
		isShowDialog(val) {
			this.isShowDialogData = val;
		}
	}
};
